-- Editing contracts for the remaining fixed catalogues. Existing item data is unchanged.
WITH patches(type_id, fields) AS (VALUES
  (1, $fields$[{"key":"weight","name":"Вес, фнт.","type":"float"},{"key":"range_min","name":"Дистанция мин","type":"int","show_on":{"key":"tags","value":[1,4,6,11]}},{"key":"range_max","name":"Дистанция макс","type":"int","show_on":{"key":"tags","value":[1,4,6,11]}}]$fields$::jsonb),
